// Planted mutation: a brand-new production module the proof manifest has
// never seen. Discovery must be closed over the whole server module tree, so
// BOTH methods of the chained ghost route below are discovered and the
// equality check fails.
use axum::routing::get;
use axum::Router;

pub fn ghost_router() -> Router {
    Router::new()
        .route("/ghost-probe", get(ghost_handler).post(ghost_handler))
}

async fn ghost_handler() -> &'static str {
    "ghost"
}
